FONT = Path("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf")
FONT_BOLD = Path("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf")


def _pdf_report(path: Path) -> None:
    """Справка в PDF с таблицей: текстовый слой, как у выгрузки из офиса."""
    from fpdf import FPDF

    pdf = FPDF()
    pdf.add_page()
    pdf.add_font("DejaVu", "", str(FONT))
    pdf.add_font("DejaVu", "B", str(FONT_BOLD))
    pdf.set_font("DejaVu", "B", 15)
    pdf.multi_cell(0, 8, "Инициатива «Зелёный склад»: итоги трёх кварталов")
    pdf.ln(3)
    pdf.set_font("DejaVu", "", 11)
    for text in (
        "Цель инициативы — снизить потребление энергии и количество упаковки на "
        "распределительном центре в Подольске без роста себестоимости обработки заказа.",
        "Меры: светодиодное освещение с датчиками движения, рекуперация энергии на "
        "погрузчиках, многоразовая тара для внутренних перемещений и оптимизация "
        "размеров коробок под заказ.",
    ):
        pdf.multi_cell(0, 6, text)
        pdf.ln(2)
    rows = (
        ("Показатель", "Q1", "Q2", "Q3"),
        ("Электроэнергия, МВт·ч", "412", "365", "318"),
        ("Упаковка, тонн", "96", "81", "70"),
        ("Стоимость обработки заказа, руб", "54", "53", "52"),
    )
    with pdf.table(col_widths=(80, 30, 30, 30)) as table:
        for row in rows:
            cells = table.row()
            for text in row:
                cells.cell(text)
    pdf.ln(4)
    for text in (
        "За три квартала потребление энергии снизилось на 23 %, упаковки — на 27 %. "
        "Стоимость обработки заказа не выросла, а снизилась на 2 рубля.",
        "Предложение: распространить инициативу на распределительные центры в Казани "
        "и Екатеринбурге в следующем году.",
    ):
        pdf.multi_cell(0, 6, text)
        pdf.ln(2)
    pdf.output(str(path))


